void DsStoreAddtidB32Vds::execute_impl(amdgpu::Wavefront &wf) {
  auto d = std::make_unique<amdgpu::VectorMemState>(amdgpu::LOCAL_MEM);
  d->elem_size = 4;
  d->num_elems = 1;
  d->is_load = false;
  d->wait_counter_type = amdgpu::WaitCounterType::DSCNT;
  {
    uint64_t exec = wf.exec();
    d->lane_mask = exec;
    d->exec_mask = exec;
    d->wg_id = wf.wg_id();
    d->wf_id = wf.wf_id();
    uint32_t offset = (static_cast<uint32_t>(inst_.offset1) << 8) | inst_.offset0;
    uint32_t m0 = wf.m0();
    for (uint32_t lane = 0; lane < wf.wf_size(); ++lane) {
      if (!(exec & (1ULL << lane)))
        continue;
      uint32_t lane_offset = (m0 + lane * 4U) & 0xFFFFFU;
      d->per_lane_addr[lane] = lane_offset + offset + wf.lds_base();
    }
  }
  auto &cu = wf.cu();
  uint64_t exec = wf.exec();
  uint32_t data_base =
      wf.vgpr_alloc().base +
      *Isa::resolved_vgpr_offset(wf, data0.opr_type_, data0.encoding_value_, data0.vgpr_msb_role());
  d->store_data.resize(wf.wf_size() * 4);
  for (uint32_t lane = 0; lane < wf.wf_size(); ++lane) {
    if (!(exec & (1ULL << lane)))
      continue;
    uint32_t val0 = amdgpu::RegisterAccess(cu).read_vgpr(data_base, lane);
    std::memcpy(&d->store_data[lane * 4], &val0, 4);
  }
  set_data(std::move(d));
}

